"""Visual evidence for a selected IDOL corrective-stage trial, not full web promotion."""
import argparse
from datetime import datetime, timezone
import html
import json
from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[1] / 'reports/idol'


def esc(value): return html.escape(str(value), quote=True)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('run')
    parser.add_argument('webgpu', help='Explicit WebGPU evidence filename in this run')
    args = parser.parse_args()
    if not re.fullmatch(r'portability-\d{8}-\d{6}-[0-9a-f]{6}', args.run): raise ValueError('Invalid trial ID')
    if not re.fullmatch(r'webgpu-[0-9TZ.-]+\.json', args.webgpu): raise ValueError('Invalid browser evidence name')
    folder = ROOT / args.run
    read = lambda name: json.loads((folder / name).read_text(encoding='utf-8'))
    native, web, run = read('metrics.json'), read(args.webgpu), read('run.json')
    if native['status'] != 'native-correctives-passed' or run['exitCode'] != 0 or not web['pass']:
        raise ValueError('This report requires successful native and browser evidence')
    if web['nativeRun'] != run['id'] or web['packageSha256'] != native['package']['sha256']:
        raise ValueError('Browser result belongs to a different package')
    if [x['name'] for x in web['cases']] != [x['name'] for x in native['cases']] or any(not x['passed'] for x in native['cases'] + web['cases']):
        raise ValueError('Incomplete parity checks')
    n = native['package']
    maxima = {key: max(c[key] for c in native['cases']) for key in native['limits']}
    gpu_max = max(max(c['poseMaxAbs'], c['shapeMaxAbs']) for c in web['cases'])
    previous = {key: max(c['againstPreviousNative'][key] for c in native['cases'] if c.get('againstPreviousNative'))
                for key in ['centerMaxDistance', 'covarianceMaxRelative']}
    benchmark = web['benchmark']
    summary = dict(generatedAt=datetime.now(timezone.utc).isoformat(), nativeRun=run['id'], browserEvidence=args.webgpu,
        runtimeCorrectionBytes=n['bytes'], nativeCases=len(native['cases']), browserCases=len(web['cases']),
        nativeMaxima=maxima, browserMaxAbs=gpu_max, benchmark={k:v for k,v in benchmark.items() if k != 'samples'},
        browserAvatarPromoted=False, qualityWinner=None,
        decision='Corrective coefficients are compact and the isolated WebGPU field stage passes. Full IDOL browser deformation remains open.')
    budget = ''.join(f'<tr><td><code>{esc(name)}</code></td><td>{size/1e6:.3f} MB</td></tr>' for name,size in n['arrayBytes'].items())
    paired = []
    for row in native['renderComparisons']:
        name = row['name']
        title = ('Author illustrated fixture' if name.startswith('source-0') else 'Shared grayscale fixture') + ' / ' + name.split('-')[-1]
        figures = ''.join(f'<figure><a href="{name}-{tag}.png"><img loading="lazy" src="{name}-{tag}.png" alt="{esc(title)}: {label}"></a><figcaption>{label}</figcaption></figure>'
                          for tag,label in [('native','Native dense corrective fields'),('compact','Compact fields + native geometry'),('diff64','Absolute pixel difference ×64')])
        paired.append(f'<article class="pair"><h3>{esc(title)}</h3><div class="gallery">{figures}</div><p class="fine">Float image max |Δ| {row["maxPixelFloatError"]:.2e}; mean {row["meanPixelFloatError"]:.2e}. Difference gain is 64 before 8-bit display; tiny errors round to black.</p></article>')
    windows = ''.join(f'<tr><td>{i+1}</td><td>{w["iterations"]}</td><td>{w["totalMs"]/1000:.2f}s</td><td>{w["p50Ms"]:.1f} ms</td><td>{w["p95Ms"]:.1f} ms</td></tr>' for i,w in enumerate(benchmark['windows']))
    cases = ''.join(f'<tr><td>{esc(a["name"])}</td><td>{a["correctiveMaxAbs"]:.2e}</td><td>{a["centerMaxDistance"]:.2e}</td><td>{a["covarianceMaxRelative"]:.2e}</td><td>{max(b["poseMaxAbs"],b["shapeMaxAbs"]):.2e}</td></tr>' for a,b in zip(native['cases'], web['cases']))
    body = '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>IDOL · Compact corrective fields / Gaussian Avatar Lab</title><style>
:root{--paper:#f6f5ef;--ink:#193235;--muted:#637575;--line:#d8dfd8;--green:#146950;--pale:#e5eee5;--amber:#845b2c}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.65 system-ui,Segoe UI,sans-serif}a{color:var(--green);text-underline-offset:3px}header,main,footer{max-width:1180px;margin:auto;padding:24px 36px}header{display:flex;justify-content:space-between;gap:20px;border-bottom:1px solid var(--line);font-size:11px;letter-spacing:.08em}.eyebrow{font-size:11px;font-weight:750;letter-spacing:.14em;text-transform:uppercase;color:var(--green)}h1{font:500 clamp(42px,5.5vw,76px)/1.08 Georgia,serif;letter-spacing:-.035em;margin:20px 0}h1 em{color:var(--green);font-weight:400}h2{font:500 34px/1.2 Georgia,serif;letter-spacing:-.02em;margin:14px 0 24px}h3{font-size:17px;margin:12px 0}.hero{padding:42px 0 28px}.lede{font-size:21px;max-width:870px;color:var(--muted)}.notice{padding:18px 22px;background:var(--pale);border-left:3px solid var(--green);border-radius:0 8px 8px 0}.warn{background:#f2e9db;border-color:var(--amber)}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;background:var(--line);border:1px solid var(--line);border-radius:10px;overflow:hidden;margin:24px 0}.stats>div{background:white;padding:20px}.stats b{font:34px Georgia,serif;display:block}.stats span{display:block;font-size:12px;color:var(--muted);margin-top:9px}section{padding:36px 0;border-top:1px solid var(--line)}.columns{display:grid;grid-template-columns:1fr 1fr;gap:28px}.card{background:white;border:1px solid var(--line);border-radius:12px;padding:22px}.fine{font-size:12px;color:var(--muted)}.bar{margin:20px 0}.bar label{display:flex;justify-content:space-between;font-size:12px;gap:10px;margin-bottom:8px}.track{height:15px;background:#e6e9e1;border-radius:4px;overflow:hidden}.track i{display:block;height:100%;background:var(--green);min-width:2px}.track.gray i{background:#929c95}.flow{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:24px 0}.flow .card{position:relative}.flow b{display:block}.flow p{font-size:13px;color:var(--muted);margin-bottom:0}.flow .card:not(:last-child):after{content:'→';position:absolute;right:-13px;top:42%;z-index:1;color:var(--green)}.formula{font:14px/1.9 ui-monospace,monospace;overflow-wrap:anywhere;background:#1a3437;color:#eff4e8;padding:22px;border-radius:10px;margin:20px 0}.topology{display:block;width:100%;background:#fff;border:1px solid var(--line);border-radius:10px}.gallery{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}figure{margin:0;border:1px solid var(--line);border-radius:9px;overflow:hidden;background:white}figure img{display:block;width:100%;aspect-ratio:640/896;object-fit:contain}figcaption{padding:12px;font-size:12px;border-top:1px solid var(--line)}.pair{margin:32px 0}table{width:100%;border-collapse:collapse;font-size:13px}td,th{padding:12px 10px;border-bottom:1px solid var(--line);text-align:left}th{font-size:11px;text-transform:uppercase;letter-spacing:.04em;color:var(--muted)}.scroll{overflow:auto}code{font:12px ui-monospace,monospace;overflow-wrap:anywhere}details{border:1px solid var(--line);border-radius:10px;background:#fff;padding:18px 22px;margin:20px 0}summary{font-weight:650;cursor:pointer}.check{color:var(--green);font-weight:700}.pending{color:var(--amber);font-weight:700}li{margin:10px 0}.roadmap{counter-reset:step;list-style:none;padding:0}.roadmap li{padding:18px 20px 18px 58px;background:white;border:1px solid var(--line);border-radius:10px;position:relative}.roadmap li:before{counter-increment:step;content:counter(step);position:absolute;left:20px;top:18px;color:var(--green);font:24px Georgia,serif}footer{font-size:12px;color:var(--muted);padding-bottom:50px}@media(max-width:800px){header,main,footer{padding-left:20px;padding-right:20px}.columns{grid-template-columns:1fr}.stats{grid-template-columns:1fr 1fr}.flow{grid-template-columns:1fr}.flow .card:not(:last-child):after{content:'↓';right:24px;top:auto;bottom:-19px}.gallery{gap:7px}figcaption{font-size:10px;padding:8px}h2{font-size:30px}}@media(max-width:420px){header{font-size:9px}.gallery{grid-template-columns:1fr 1fr}.gallery figure:last-child{grid-column:1/-1;max-width:50%;justify-self:center}.stats>div{padding:15px}.stats b{font-size:29px}}
</style></head><body><header><span>GAUSSIAN AVATAR LAB / RESEARCH NOTE 04</span><a href="../index.html">← Native generation evidence</a></header><main>
<div class="hero"><div class="eyebrow">09 September 2026 · IDOL portability spike</div><h1>Keep the correctives.<br><em>Shrink the representation.</em></h1><p class="lede">The large deformation basis is not a browser dead end. One verified subdivision level plus exact block sparsity makes its corrective fields practical to test on the GPU.</p><p class="notice"><strong>Result: native and WebGPU corrective checks pass.</strong> This is a compact correction-stage package, not a complete IDOL avatar, a new web backend, or a quality ranking.</p><div class="stats"><div><b>@@MB@@ MB</b><span>Correction package, including mappings</span></div><div><b>@@COUNT@@ / @@COUNT@@</b><span>Native and browser cases pass separately</span></div><div><b>@@P50@@ ms</b><span>Median corrective dispatch + readback</span></div><div><b>@@P95@@ ms</b><span>95th percentile · same partial stage</span></div></div></div>
<section><div class="eyebrow">01 / What changed</div><h2>Representation changes. No coefficient pruning.</h2><div class="columns"><div><p>The native cache stores 486 pose features at 100,966 vertices. The mesh connectivity exposes 25,254 coarse vertices and 75,712 edge midpoints. Every midpoint pose coefficient reconstructs bit-for-bit; shape coefficients reconstruct numerically exactly, with 51,229 signed-zero bit differences.</p><p>We store only the coarse coefficients. A sparse row records each supported bone’s complete 9 × 3 float32 block. There is no quantization, low-rank approximation, magnitude threshold, top-k truncation, or neural retraining.</p><p class="fine">Simple whole-vertex deduplication barely helped: 100,702 distinct pose rows out of 100,966. A second subdivision level failed topology checks and was not used. Negative results stay in the <a href="../basis-20260909-150123-c774b1/metrics.json">dictionary audit</a> and <a href="../structure-20260909-152507-c98ff5/metrics.json">hierarchy audit</a>.</p></div><div class="card"><div class="bar"><label><span>Original dense pose directions</span><b>588.83 MB</b></label><div class="track gray"><i style="width:100%"></i></div></div><div class="bar"><label><span>Coarse dense pose directions</span><b>147.28 MB</b></label><div class="track"><i style="width:25%"></i></div></div><div class="bar"><label><span>Sparse pose values + CSR indices</span><b>64.94 MB</b></label><div class="track"><i style="width:11.03%"></i></div></div><p class="fine">Bars show pose data only. Adding 6.06 MB shape data and 3.02 MB mappings gives the full 74.02 MB corrective package. Decimal MB throughout; no compression codec or validation fixtures included.</p></div></div>
<svg class="topology" viewBox="0 0 960 220" role="img" aria-label="Three coarse coefficients define midpoint coefficients; evaluate coarse fields once, then average endpoints and face corners"><g fill="none" stroke="#8eaba0" stroke-width="2"><path d="M45 175 L150 35 L255 175 Z M98 105 L203 105 L150 175 Z"/><path d="M290 112 H350 M343 105 L350 112 L343 119"/></g><g fill="#146950"><circle cx="45" cy="175" r="7"/><circle cx="150" cy="35" r="7"/><circle cx="255" cy="175" r="7"/></g><g fill="#e7ab57"><circle cx="98" cy="105" r="6"/><circle cx="203" cy="105" r="6"/><circle cx="150" cy="175" r="6"/></g><g font-family="system-ui,sans-serif" fill="#193235"><text x="30" y="204" font-size="14">a</text><text x="146" y="23" font-size="14">b</text><text x="264" y="195" font-size="14">c</text><text x="380" y="65" font-size="21">B(midpoint) = ½ [B(a) + B(b)]</text><text x="380" y="103" font-size="16">Measured for every pose and shape coefficient.</text><text x="380" y="142" font-size="16">Evaluate 25,254 coarse vertices → reconstruct 100,966.</text><text x="380" y="180" font-size="16">Average each triangle’s corners → 200,800 Gaussian fields.</text></g></svg><p class="fine">Schematic topology, not the avatar mesh. Orange nodes are derived coefficients. Equality of stored coefficients does not imply bitwise-equal floating-point evaluation after reordering; both native and browser arithmetic were tested.</p></section>
<section><div class="eyebrow">02 / The browser stage in pipeline order</div><h2>506 numbers in. Two correction vectors per splat out.</h2><div class="flow"><div class="card"><span class="eyebrow">Compute pass 1</span><b>Sparse coarse evaluation</b><p>486 entries of non-root rotation matrices minus identity, plus 10 body-shape and 10 expression coefficients. Accumulate supported pose blocks and dense shape directions.</p></div><div class="card"><span class="eyebrow">Compute pass 2</span><b>Midpoint reconstruction</b><p>Read two already-evaluated coarse endpoints for each added vertex. Average shape and pose vectors separately. Parents never refer to newly written vertices.</p></div><div class="card"><span class="eyebrow">Compute pass 3</span><b>Gaussian face pooling</b><p>Average the three vertex vectors for each Gaussian’s face. Produce shape XYZ and pose XYZ, each padded to a vec4. Read back 6.43 MB for validation.</p></div></div><div class="formula">poseFeature = flatten(R₁ − I, …, R₅₄ − I)<br>coarsePose[v] = Σ supportedBone Σ matrixEntry B[v,b,e] · poseFeature[b,e]<br>coarseShape[v] = Σₖ S[v,k] · coefficient[k]<br>gaussianField[g] = (field[face₀] + field[face₁] + field[face₂]) / 3</div><p>The 506 numbers are a <strong>low-level corrective input</strong>, not 506 independent user sliders. This trial obtains rotation features and shape/expression coefficients from native SMPL-X. Browser FK, hand means, semantic expression mapping and controller/Mixamo resolution are not implemented for IDOL here.</p><div class="columns"><div class="card"><h3>Explicit experimental contract</h3><code>idol-corrective-field-subdivision-v1-lab</code><p>SHA-256-checked binary, fixed layouts, aligned ranges, validated CSR offsets/bone IDs and topology indices. Reject nonfinite values, invalid controls, overlapping evaluations, or a destroyed device. No silent GPU fallback.</p><p><a href="correctives.json">Array manifest</a> · <a href="../../../idol/corrective_gpu.mjs">GPU implementation</a> · <a href="../../../idol/corrective_codec.py">Encoder</a></p></div><div class="card"><h3>Payload budget</h3><table><thead><tr><th>Array</th><th>Bytes / decimal MB</th></tr></thead><tbody>@@BUDGET@@</tbody></table><p class="fine">Owned GPU buffers total @@GPU_MB@@ MB, including intermediate output and readback. This is not total browser VRAM. A complete avatar also needs appearance, canonical geometry, rig and bindings.</p></div></div></section>
<section><div class="eyebrow">03 / Verification, not visual guesswork</div><h2>Two independent comparisons against native fields.</h2><p>The frozen set contains 16 saved native cases across two avatars, 55 one-joint probes, 20 single shape/expression probes, and 8 seeded combined cases. Each browser case compares all 1,204,800 non-padding scalar outputs against a hashed dense-native reference.</p><div class="scroll"><table><thead><tr><th>Comparison</th><th>Worst observed</th><th>Frozen acceptance limit</th><th>Result</th></tr></thead><tbody><tr><td>Compact Torch fields vs native dense fields</td><td>@@FIELD@@ max absolute</td><td>1 × 10⁻⁵</td><td class="check">PASS</td></tr><tr><td>Native centers after replacing only corrective fields</td><td>@@CENTER@@ max distance</td><td>5 × 10⁻⁶</td><td class="check">PASS</td></tr><tr><td>Native covariance after replacing only corrective fields</td><td>@@COV@@ relative packed-vector error</td><td>1 × 10⁻³</td><td class="check">PASS</td></tr><tr><td>WebGPU fields vs native dense fields</td><td>@@GPU_ERR@@ max absolute</td><td>1 × 10⁻⁵</td><td class="check">PASS</td></tr></tbody></table></div><p class="fine">Native coordinates are not asserted to be calibrated meters. Relative covariance uses the norm of six packed symmetric entries, not a full-matrix Frobenius norm. Fresh native geometry also matches the 16 previously saved fixtures within the same limits: center @@PREV_CENTER@@, covariance @@PREV_COV@@. GPU readbacks were not fed through the downstream native renderer; GPU validation here ends at corrective fields.</p><details><summary>All @@COUNT@@ numerical cases</summary><div class="scroll"><table><thead><tr><th>Case</th><th>Torch field |Δ|</th><th>Center distance</th><th>Covariance relative</th><th>GPU field |Δ|</th></tr></thead><tbody>@@CASES@@</tbody></table></div></details><p><a href="metrics.json">Native results</a> · <a href="@@WEB_FILE@@">Browser results</a> · <a href="validation.json">Reference/control ledger</a> · <a href="run.json">Native command, source revisions and hashes</a></p></section>
<section><div class="eyebrow">04 / Native image evidence</div><h2>What the representation change looks like.</h2><p>These are real paired native rasterizations using dense versus compact-computed corrections. All other geometry stages remain native. They test fidelity of the representation change, not whether the generated identity or clothing is correct.</p>@@PAIRS@@</section>
<section><div class="eyebrow">05 / Measured browser cost</div><h2>@@P50@@ ms median. Only the correction stage.</h2><p>Chromium, NVIDIA Lovelace WebGPU adapter, existing RTX 4090 workstation. Generation had exited before timing. After 30 warm-up evaluations, three 300-evaluation windows cycle eight combined-control cases. The total sample covers @@SECONDS@@ seconds, not a long-session or headset test.</p><div class="scroll"><table><thead><tr><th>Window</th><th>Evaluations</th><th>Duration</th><th>Median</th><th>95th percentile</th></tr></thead><tbody>@@WINDOWS@@</tbody></table></div><p class="notice warn"><strong>Do not read this as animation FPS.</strong> Timing includes control upload, three compute passes, GPU readback and CPU copying. It excludes forward kinematics, skinning, three-neighbor size estimation, covariance processing, sorting, compositing and the application loop.</p><p class="fine">Initialization was @@LOAD@@ ms for localhost range download + hashing, @@DECODE@@ ms for CPU layout checks, and @@UPLOAD@@ ms for shader compilation + buffer upload. These are local harness costs, not internet loading predictions. Validation binaries are separate from the 74 MB runtime package.</p></section>
<section><div class="eyebrow">06 / What did not work</div><h2>Keep the failed paths in the ledger.</h2><ul><li><strong>Dictionary encoding:</strong> almost every full pose row is unique; it did not solve the payload problem. Subdivision plus bone-block sparsity did.</li><li><strong>A second coarse level:</strong> parent topology failed the four-child test. Only the independently verified first level is used.</li><li><strong>Initial validation harness:</strong> native saved centers had shape N × 1 × 3. Subtracting N × 3 would broadcast to N × N × 3 and attempted a 450 GiB allocation. The system-drive guard stopped the owned trial; the next run exposed the CUDA error. Explicit shape checks and reshape-at-load fixed this diagnostic bug. Both failed records remain: <a href="../portability-20260909-151336-cda541/run.json">first stop</a>, <a href="../portability-20260909-151950-3fa31c/metrics.json">diagnosed run</a>.</li><li><strong>Local large HTTP responses:</strong> the initial browser harness received empty 204 responses. Bounded 4 MiB ranges with distinct range URLs and full reassembled SHA-256 checks succeeded. No integrity check was disabled. Early failed browser ledgers remain beside the successful one.</li></ul><p>No model weights, vendor source, drivers, system configuration, existing LHM/LHM++ environment, main app implementation or default avatar was changed. No additional model download or licensed-template acceptance was needed for this spike.</p></section>
<section><div class="eyebrow">07 / Next gates, in dependency order</div><h2>One blocker reduced. A full port is still work.</h2><ol class="roadmap"><li><strong>Export the complete native deformation contract.</strong> Canonical frame, exact full-influence weights, native hand means, rest/corrective conventions and 10-expression schema. Validate browser joint transforms, including shape-dependent rest joints.</li><li><strong>Resolve posed-neighbor sizes and covariance.</strong> Preserve the native three-nearest-neighbor rule and nonorthogonal covariance transport. If a faster approximation is needed, name it and measure its error separately; do not label it native parity.</li><li><strong>Prove a complete browser avatar.</strong> Run arbitrary controls, Mixamo, record/replay and remote signals, compare full centers/covariances/renders to native, then profile the whole loop and sustained memory use. No static-frame or PLY shortcut establishes this.</li><li><strong>Make the quality decision with consented captures.</strong> Matched input photos and frozen holdouts across LHM 500M/1B, LHM++ and IDOL. These bundled engineering fixtures do not establish an identity-quality winner or permission to ship.</li></ol><p class="notice">LHM-500M remains the default. LHM++ remains the implemented multi-photo web path. IDOL remains an isolated research challenger, now with a verified compact corrective stage.</p><p><a href="../index.html">Native generation report and paper/source provenance</a> · <a href="../../../idol/README.md">Reproduction guide</a> · <a href="../../../../../generation-experiments-plan.md">Overall research plan</a> · <a href="summary.json">This report’s ledger</a></p></section>
</main><footer>Local engineering evidence · actual native renders · no held-out quality ranking · no Unity/Meta promotion · no commercial-use clearance.</footer></body></html>'''
    replace = dict(MB=f'{n["bytes"]/1e6:.2f}',COUNT=len(native['cases']),P50=f'{benchmark["p50Ms"]:.1f}',P95=f'{benchmark["p95Ms"]:.1f}',
        BUDGET=budget,GPU_MB=f'{web["adapter"]["ownedBufferBytes"]/1e6:.2f}',FIELD=f'{maxima["correctiveMaxAbs"]:.2e}',
        CENTER=f'{maxima["centerMaxDistance"]:.2e}',COV=f'{maxima["covarianceMaxRelative"]:.2e}',GPU_ERR=f'{gpu_max:.2e}',
        PREV_CENTER=f'{previous["centerMaxDistance"]:.2e}',PREV_COV=f'{previous["covarianceMaxRelative"]:.2e}',
        CASES=cases,WEB_FILE=esc(args.webgpu),PAIRS=''.join(paired),WINDOWS=windows,SECONDS=f'{benchmark["totalMs"]/1000:.2f}',
        LOAD=f'{web["initializationMs"]["downloadAndHash"]:.0f}',DECODE=f'{web["initializationMs"]["decodeAndValidate"]:.0f}',
        UPLOAD=f'{web["initializationMs"]["compileAndUpload"]:.0f}')
    for key,value in replace.items(): body = body.replace('@@'+key+'@@',str(value))
    regressions = folder / 'regression-checks.json'
    if regressions.is_file() and json.loads(regressions.read_text(encoding='utf-8')).get('pass'):
        body = body.replace('<details><summary>All ', '<p class="fine">Scoped regressions also pass: 28 Python tests (12 IDOL + 16 existing), 21 JavaScript tests (4 corrective + 17 existing), and TypeScript. The baseline avatar hashes and pinned vendor checkout are unchanged. The main application browser suite was not rerun. <a href="regression-checks.json">Actual regression outputs</a>.</p><details><summary>All ', 1)
    if '@@' in body: raise ValueError('Unresolved template placeholder')
    (folder / 'index.html').write_text(body,encoding='utf-8')
    (folder / 'summary.json').write_text(json.dumps(summary,indent=2),encoding='utf-8')
    print(folder / 'index.html')


if __name__ == '__main__': main()
